package ai.interviewiq.api;

import com.fasterxml.jackson.databind.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import java.util.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class MvpFlowIntegrationTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json; String token,email; long company,role,difficulty;
 @BeforeEach void setup() throws Exception { String suffix=UUID.randomUUID().toString().substring(0,8); email="user"+suffix+"@example.com"; String auth=mvc.perform(post("/api/v1/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"displayName\":\"Test User\",\"email\":\""+email+"\",\"password\":\"SecurePassword123\"}" )).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();token=json.readTree(auth).path("accessToken").asText();company=id("/api/v1/companies");role=id("/api/v1/job-roles");difficulty=id("/api/v1/difficulty-levels"); }
 long id(String url)throws Exception{return json.readTree(mvc.perform(get(url).header("Authorization","Bearer "+token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).get(0).path("id").asLong();}
 @Test void registrationValidationDuplicateLoginAndProtection() throws Exception {mvc.perform(post("/api/v1/auth/register").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"displayName\":\"Test User\",\"email\":\""+email+"\",\"password\":\"SecurePassword123\"}" )).andExpect(status().isConflict());mvc.perform(get("/api/v1/users/me")).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"missing@example.com\",\"password\":\"bad\"}" )).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"SecurePassword123\"}" )).andExpect(status().isOk()).andExpect(jsonPath("$.accessToken").isNotEmpty());mvc.perform(get("/api/v1/users/me").header("Authorization","Bearer "+token)).andExpect(status().isOk());}
@Test void interviewAnswerCompletionAndHistoryOwnership() throws Exception {String body="{\"companyId\":"+company+",\"jobRoleId\":"+role+",\"difficultyLevelId\":"+difficulty+"}"; JsonNode session=json.readTree(mvc.perform(post("/api/v1/interview-sessions").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());long id=session.path("id").asLong();mvc.perform(get("/api/v1/interview-sessions/"+id).header("Authorization","Bearer "+token)).andExpect(status().isOk());mvc.perform(post("/api/v1/interview-sessions/"+id+"/start").header("Authorization","Bearer "+token)).andExpect(status().isOk());for(JsonNode q:session.path("questions")){mvc.perform(put("/api/v1/interview-sessions/"+id+"/questions/"+q.path("id").asLong()+"/answer").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"answerText\":\"A complete answer\",\"inputMethod\":\"TYPED\"}")).andExpect(status().isOk());}mvc.perform(post("/api/v1/interview-sessions/"+id+"/complete").header("Authorization","Bearer "+token)).andExpect(status().isAccepted()).andExpect(jsonPath("$.status").value("AVAILABLE"));mvc.perform(get("/api/v1/interview-sessions").header("Authorization","Bearer "+token)).andExpect(status().isOk());mvc.perform(get("/api/v1/interview-sessions/"+id).header("Authorization","Bearer invalid")).andExpect(status().isUnauthorized()); String otherAuth=mvc.perform(post("/api/v1/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"displayName\":\"Other User\",\"email\":\"other"+UUID.randomUUID().toString().substring(0,8)+"@example.com\",\"password\":\"SecurePassword123\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString(); String otherToken=json.readTree(otherAuth).path("accessToken").asText(); mvc.perform(get("/api/v1/interview-sessions/"+id).header("Authorization","Bearer "+otherToken)).andExpect(status().isNotFound());}
@Test void rejectsMalformedTokenAndInvalidLifecycleTransitions() throws Exception { mvc.perform(get("/api/v1/users/me").header("Authorization","Bearer malformed.token.value")).andExpect(status().isUnauthorized()); JsonNode session=create(); long id=session.path("id").asLong(); long question=session.path("questions").get(0).path("id").asLong(); mvc.perform(put("/api/v1/interview-sessions/"+id+"/questions/"+question+"/answer").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"answerText\":\"answer\",\"inputMethod\":\"TYPED\"}")).andExpect(status().isConflict()); mvc.perform(post("/api/v1/interview-sessions/"+id+"/complete").header("Authorization","Bearer "+token)).andExpect(status().isConflict()); }
@Test void protectsPdfFeedbackAndAnalyticsAcrossUsers() throws Exception { JsonNode session=complete(create()); long id=session.path("id").asLong(); mvc.perform(get("/api/v1/interview-sessions/"+id+"/report/pdf").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(header().string("Content-Type",org.hamcrest.Matchers.containsString("application/pdf"))).andExpect(result->org.junit.jupiter.api.Assertions.assertTrue(result.getResponse().getContentAsByteArray().length>100)); String other=register("Other"); mvc.perform(get("/api/v1/interview-sessions/"+id+"/report/pdf").header("Authorization","Bearer "+other)).andExpect(status().isNotFound()); mvc.perform(get("/api/v1/interview-sessions/"+id+"/feedback").header("Authorization","Bearer "+other)).andExpect(status().isNotFound()); mvc.perform(get("/api/v1/analytics/overview").header("Authorization","Bearer "+other)).andExpect(status().isOk()).andExpect(jsonPath("$.completedInterviews").value(0)); mvc.perform(get("/api/v1/interview-sessions").param("status","COMPLETED").param("limit","1").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.data.length()").value(1)); }
private JsonNode create() throws Exception {return json.readTree(mvc.perform(post("/api/v1/interview-sessions").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"companyId\":"+company+",\"jobRoleId\":"+role+",\"difficultyLevelId\":"+difficulty+"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());}
private JsonNode complete(JsonNode session) throws Exception {long id=session.path("id").asLong();mvc.perform(post("/api/v1/interview-sessions/"+id+"/start").header("Authorization","Bearer "+token)).andExpect(status().isOk());for(JsonNode q:session.path("questions"))mvc.perform(put("/api/v1/interview-sessions/"+id+"/questions/"+q.path("id").asLong()+"/answer").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"answerText\":\"A complete answer with enough detail for evaluation.\",\"inputMethod\":\"TYPED\"}")).andExpect(status().isOk());mvc.perform(post("/api/v1/interview-sessions/"+id+"/complete").header("Authorization","Bearer "+token)).andExpect(status().isAccepted());return session;}
private String register(String name)throws Exception{String response=mvc.perform(post("/api/v1/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"displayName\":\""+name+"\",\"email\":\""+UUID.randomUUID()+"@example.com\",\"password\":\"SecurePassword123\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();return json.readTree(response).path("accessToken").asText();}
}
